using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class FluidBridgeOperations:RefCounted
{
    private readonly FluidSettingsOperations _fluidSettings=new();private readonly ActorAnimationOperations _animation=new();private readonly ActorRuntimeOperations _clips=new();private readonly PhysicsSettingsOperations _settings=new();private readonly PhysicsGeometryOperations _geometry=new();private readonly PhysicsCollisionWorldOperations _collision=new();
    private static Settings Map(GodotObject owner,string key)=>owner.Get(key).AsGodotDictionary();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var result)?result:fallback;private static GodotObject Object(GodotObject owner,string key)=>owner.Get(key).AsGodotObject();private static Resource Actor(RefCounted controller,string id)=>Map(controller,"prototypes")[id].AsGodotDictionary()["actor"].As<Resource>();private static GDScript Solver()=>GD.Load<GDScript>("res://scripts/actors/physics/fluid/fluid_solver.gd");
    public void reset(RefCounted owner){_collision.reset(owner.Get("proxies").As<RefCounted>());Map(owner,"proxy_owners").Clear();Map(owner,"environment_documents").Clear();owner.Get("environment_water").AsGodotArray().Clear();var compute=owner.Get("compute").AsGodotObject();if(compute!=null){compute.Call("dispose");owner.Set("compute",default(Variant));}}
    public void ensure_compute(RefCounted owner){if(owner.Get("compute").AsGodotObject()==null)owner.Set("compute",GD.Load<GDScript>("res://scripts/actors/physics/fluid/fluid_compute.gd").New());}
    public void prepare_environment(RefCounted owner,RefCounted controller,double time)
    {
        var water=owner.Get("environment_water").AsGodotArray();water.Clear();var model=Object(controller,"_model");var documents=Map(owner,"environment_documents");foreach(var value in model.Get("actors").AsGodotArray()){var actor=value.As<Resource>();if(actor.Get("type_id").AsString()!="environment_asset")continue;var clip=model.Call("clip_for_actor_id",actor.Get("id")).As<Resource>();if(clip==null||!_clips.contains_time(clip,time))continue;var values=_animation.sampled_values(actor,controller.Call("_local",actor,time).AsDouble());string path=Get(values,"environment_path","").AsString();if(path.Length==0)continue;var runtime=controller.Call("_runtime",actor.Get("id")).AsGodotObject();if(runtime!=null&&runtime.HasMethod("environment_for_physics")&&runtime.Get("source_path").AsString()==path){var document=runtime.Call("environment_for_physics").As<Resource>();if(ActorDataOperations.ScriptIs(document,"res://Workspaces/EnvironmentWorkspace/environment_document.gd"))water.Add(new Settings{["document"]=document,["pose"]=controller.Call("animated_world",actor.Get("id"),time,true)});continue;}if(!documents.ContainsKey(path)){var document=ResourceLoader.Exists(path)?ResourceLoader.Load(path):null;bool valid=ActorDataOperations.ScriptIs(document,"res://Workspaces/EnvironmentWorkspace/environment_document.gd")&&document!.Call("validate").AsStringArray().Length==0;documents[path]=valid?Variant.From(document!):default;}if(documents[path].AsGodotObject() is Resource prepared)water.Add(new Settings{["document"]=prepared,["pose"]=controller.Call("animated_world",actor.Get("id"),time,true)});}
    }
    public Settings environment_at(RefCounted owner,Vector3 point){var result=new Settings();foreach(var value in owner.Get("environment_water").AsGodotArray()){var entry=value.AsGodotDictionary();var query=entry["document"].As<Resource>().Call("water_at",point,entry["pose"]).AsGodotDictionary();if(query.Count==0||!Get(query,"physics",true).AsBool())continue;if(result.Count==0||query["surface"].AsVector3().Y>result["surface"].AsVector3().Y)result=query;}return result;}
    public Vector3 rigid_water_acceleration(RefCounted owner,RefCounted controller,string id,Settings state,Settings config,double h)
    {
        state["water_fraction"]=0.0;if(owner.Get("environment_water").AsGodotArray().Count==0||!Get(config,"water_interaction",true).AsBool()||h<=0)return Vector3.Zero;var localBounds=Map(controller,"prototypes")[id].AsGodotDictionary()["geometry"].AsGodotDictionary()["bounds"].AsAabb();var pose=state["pose"].AsTransform3D();var bounds=pose*localBounds;double volume=Math.Abs(pose.Basis.Determinant())*localBounds.Volume;if(volume<=.0000001)return Vector3.Zero;double mass=Math.Max(.001,config["mass"].AsDouble()),k=0,buoyancy=0,drag=0,cover=0;var gravity=controller.Call("_gravity",config).AsVector3();var normal=Vector3.Zero;var flow=Vector3.Zero;for(int z=0;z<3;z++)for(int x=0;x<3;x++){var center=new Vector3(bounds.Position.X+bounds.Size.X*x*.5f,bounds.GetCenter().Y,bounds.Position.Z+bounds.Size.Z*z*.5f);var water=environment_at(owner,center);if(water.Count==0)continue;var up=water["normal"].AsVector3();double height=Math.Max(.001,up.Abs().Dot(bounds.Size)),depth=Math.Clamp(up.Dot(water["surface"].AsVector3()-center)+height*.5,0,height);if(depth<=0)continue;double fraction=depth/height,stiffness=Math.Max(0,water["density"].AsDouble())*gravity.Length()*Math.Max(0,Get(config,"water_buoyancy",1.0).AsDouble())*volume/(height*9*mass);k+=stiffness;buoyancy+=stiffness*depth;normal+=up*(float)fraction;flow+=water["flow"].AsVector3()*(float)fraction;cover+=fraction;drag+=Math.Max(0,water["drag"].AsDouble())*Math.Max(0,Get(config,"water_drag",1.0).AsDouble())*fraction/9;}if(cover<=0)return Vector3.Zero;state["water_fraction"]=cover/9;normal=normal.Normalized();flow/=(float)cover;drag*=2+2*Math.Sqrt(k);var velocity=state["v"].AsVector3();double along=velocity.Dot(normal),flowAlong=flow.Dot(normal),g=gravity.Dot(normal),next=(along+h*(g+buoyancy+drag*flowAlong))/(1+h*drag+h*h*k),correction=(next-along)/h-g;var tangent=velocity-normal*(float)along;var flowTangent=flow-normal*(float)flowAlong;var damping=(flowTangent-tangent)*(float)(drag/(1+h*drag));if(correction*correction+damping.LengthSquared()>.000001)state["sleep"]=0.0;return normal*(float)correction+damping;
    }
    public Settings values(RefCounted controller,string id,double time){var actor=Actor(controller,id);return _fluidSettings.effective(_animation.sampled_values(actor,controller.Call("_local",actor,time).AsDouble()));}
    public Transform3D source(RefCounted controller,string id,Settings config,double time)=>controller.Call("source_transform",id,config,time).AsTransform3D();
    public void initialize(RefCounted controller,string id,Settings state,Settings config,double time){var fluid=controller.Get("fluid").As<RefCounted>();ensure_compute(fluid);var settings=values(controller,id,time);var pose=source(controller,id,config,time);var geometry=new Settings();var compute=Object(fluid,"compute");if(!compute.Call("available").AsBool()){settings["budget"]=Math.Min(settings["budget"].AsInt32(),256);controller.Call("_warn","Fluid uses the CPU fallback (maximum 256 particles). "+compute.Get("error").AsString());}if(settings["fluid_shape"].AsInt32()==3){var runtime=controller.Call("_runtime",settings["fluid_mesh_actor"].AsString()).AsGodotObject() as Node;if(runtime!=null)geometry=_geometry.capture(runtime,new Settings());}var volume=new Settings{["points"]=Array.Empty<Vector3>(),["error"]=""};if(settings["fluid_source_mode"].AsInt32()!=1)volume=GD.Load<GDScript>("res://scripts/actors/physics/fluid/fluid_volume.gd").Call("generate",settings,pose,geometry).AsGodotDictionary();state["fluid_error"]=volume["error"];if(volume["error"].AsString().Length>0){controller.Call("_warn",Actor(controller,id).Get("display_name").AsString()+": "+volume["error"].AsString());volume["points"]=Array.Empty<Vector3>();}Solver().Call("initialize",state,settings,volume["points"]);}
